(async (page) => {
  const browserContext = await page.context().browser().newContext();
  page = await browserContext.newPage();
  const payload = [{"item":{"id":"03.10","title":"Ternário ou if?","stage":"03","kind":"MAKE","contentVersion":1,"optional":false,"duration":"20 min","runtime":"Node.js 24 LTS · ECMAScript 2026 · módulos ES","compatibility":"Ternário e if/else fazem parte do JavaScript padrão no Node.js 24 LTS; sem dependências externas.","objective":"Antes de codificar, marque qual decisão tem duas alternativas e qual tem três; preveja os resultados para -1, 0, 45, 60 e 100.","prompt":"Implemente resumirNota(pontos). Use uma expressão ternária para faixa (\"aprovar\" quando pontos>=60, senão \"revisar\"). Use if/else if/else para situacao: \"inválida\" abaixo de 0, \"em revisão\" abaixo de 60 e \"liberada\" nos demais casos. Compare qual forma deixa cada decisão mais clara.","firstResponse":{"action":"Antes de codificar, marque qual decisão tem duas alternativas e qual tem três; preveja os resultados para -1, 0, 45, 60 e 100.","timing":"Depois de ler o exemplo e o primer de função exportada, antes de executar ou pedir dica."},"explanation":{"mental_model":"O ternário `condicao ? valorA : valorB` é uma expressão: escolhe um valor entre duas alternativas. `if/else` organiza caminhos; quando há várias condições, etapas ou efeitos, os blocos costumam deixar a decisão mais legível. Escolha pela clareza da regra, não pela quantidade de caracteres.","worked_example":"Para uma nota, `const faixa = pontos >= 60 ? \"aprovar\" : \"revisar\"` nomeia uma escolha simples. Para três estados, `if (pontos < 0) ... else if (pontos < 60) ... else ...` mostra a ordem das faixas sem aninhar ternários.","common_trap":"Ternários aninhados podem comprimir várias decisões e ocultar a ordem dos casos. Um if longo também pode ser desnecessário quando só se escolhe entre dois valores.","why_it_matters":"Código legível facilita revisar regras de negócio e perceber limites ou casos que ficaram de fora."},"interaction":"Registre a resposta inicial e edite o código. Os testes automáticos conferem os resultados; o uso do ternário e de if, e a legibilidade, são conferidos por você na autoavaliação. Compare a expressão curta com os blocos da decisão de três faixas.","resources":["MDN conditional (ternary) operator: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Conditional_operator","MDN if...else: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/if...else"],"starterFiles":[{"path":"main.js","content":"export function resumirNota(pontos) {\n  const faixa = \"\";\n  let situacao = \"\";\n  return { faixa, situacao };\n}\n"}],"assets":[],"examples":[{"given":"pontos=75","expected":"{faixa:\"aprovar\", situacao:\"liberada\"}; pontos=45 -> {faixa:\"revisar\", situacao:\"em revisão\"}"}],"checks":[{"fixture":{"given":"pontos=75","expected":"{faixa:\"aprovar\", situacao:\"liberada\"}; pontos=45 -> {faixa:\"revisar\", situacao:\"em revisão\"}"},"scoring":"Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."}],"constraints":["Mantenha exatamente os nomes e os valores de retorno do contrato.","Não use ternários aninhados para a situação com três resultados."],"rubric":["faixa usa uma expressão ternária legível com duas alternativas.","situacao distingue as três faixas com if/else if/else na ordem correta.","A solução preserva os limites 0, 60 e 100 e explica qual forma comunica melhor cada regra.","Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."],"learningMetadata":{"requires":["02.01","03.04"]},"primers":["`export function resumirNota(pontos)` é um invólucro pronto para que o avaliador importe a função; preserve `export`, o nome e o parâmetro e altere somente o corpo indicado. Funções exportadas para módulos são aprofundadas na etapa 14.","`{ faixa, situacao }` cria um objeto com duas propriedades; a forma curta usa cada variável também como nome da propriedade. Objetos são aprofundados na etapa 06; aqui, mantenha os nomes pedidos pelo contrato."],"review":{"prompt":"Qual forma costuma comunicar melhor uma escolha de três estados com condições em ordem?","choices":["Ternários aninhados mesmo quando cada nível tem uma condição diferente","Escolher sempre a forma com menos linhas","if/else if/else com um ramo por estado"],"answer":2,"correctFeedback":"Correto: os blocos expõem a ordem dos três casos; ternário cabe melhor numa escolha curta entre dois valores.","incorrectFeedback":"A quantidade de linhas não determina legibilidade; compare quantos casos existem e se a regra fica fácil de seguir."},"preparation":{"guided":true,"stageTitle":"ETAPA 03","introduction":"Antes de codificar, marque qual decisão tem duas alternativas e qual tem três; preveja os resultados para -1, 0, 45, 60 e 100.","explanation":"O ternário `condicao ? valorA : valorB` é uma expressão: escolhe um valor entre duas alternativas. `if/else` organiza caminhos; quando há várias condições, etapas ou efeitos, os blocos costumam deixar a decisão mais legível. Escolha pela clareza da regra, não pela quantidade de caracteres.","conceptSteps":["O ternário `condicao ? valorA : valorB` é uma expressão: escolhe um valor entre duas alternativas.","`if/else` organiza caminhos; quando há várias condições, etapas ou efeitos, os blocos costumam deixar a decisão mais legível.","Escolha pela clareza da regra, não pela quantidade de caracteres.","Código legível facilita revisar regras de negócio e perceber limites ou casos que ficaram de fora."],"vocabulary":[],"workedExample":{"steps":["Para uma nota, `const faixa = pontos >= 60 ? \"aprovar\" : \"revisar\"` nomeia uma escolha simples.","Para três estados, `if (pontos < 0) ... else if (pontos < 60) ... else ...` mostra a ordem das faixas sem aninhar ternários."]},"notes":["Ternários aninhados podem comprimir várias decisões e ocultar a ordem dos casos. Um if longo também pode ser desnecessário quando só se escolhe entre dois valores.","Código legível facilita revisar regras de negócio e perceber limites ou casos que ficaram de fora."],"docs":[{"title":"MDN conditional (ternary) operator","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Conditional_operator","section":"","question":""},{"title":"MDN if...else","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/if...else","section":"","question":""}],"materials":[],"predictionGuide":"Antes de codificar, marque qual decisão tem duas alternativas e qual tem três; preveja os resultados para -1, 0, 45, 60 e 100. Depois de ler o exemplo e o primer de função exportada, antes de executar ou pedir dica.","practiceSteps":["Implemente resumirNota(pontos).","Use uma expressão ternária para faixa (\"aprovar\" quando pontos>=60, senão \"revisar\").","Use if/else if/else para situacao: \"inválida\" abaixo de 0, \"em revisão\" abaixo de 60 e \"liberada\" nos demais casos.","Restrição: Mantenha exatamente os nomes e os valores de retorno do contrato.","Restrição: Não use ternários aninhados para a situação com três resultados."],"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente resumirNota(pontos). Use uma expressão ternária para faixa (\"aprovar\" quando pontos>=60, senão \"revisar\"). Use if/else if/else para situacao: \"inválida\" abaixo de 0, \"em revisão\" abaixo de 60 e \"liberada\" nos demais casos. Compar","Compare com o exemplo público — dado: pontos=75. Esperado: {faixa:\"aprovar\", situacao:\"liberada\"}; pontos=45 -> {faixa:\"revisar\", situacao:\"em revisão\"}.","Cuidado com a armadilha desta atividade: Ternários aninhados podem comprimir várias decisões e ocultar a ordem dos casos."],"reflectionPrompt":"Compare sua primeira resposta com o resultado da tentativa. Explique a regra que você praticou e um erro que ela ajuda a evitar."},"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente resumirNota(pontos). Use uma expressão ternária para faixa (\"aprovar\" quando pontos>=60, senão \"revisar\"). Use if/else if/else para situacao: \"inválida\" abaixo de 0, \"em revisão\" abaixo de 60 e \"liberada\" nos demais casos. Compar","Compare com o exemplo público — dado: pontos=75. Esperado: {faixa:\"aprovar\", situacao:\"liberada\"}; pontos=45 -> {faixa:\"revisar\", situacao:\"em revisão\"}.","Cuidado com a armadilha desta atividade: Ternários aninhados podem comprimir várias decisões e ocultar a ordem dos casos."],"edgeCases":["pontos=0 -> {faixa:\"revisar\", situacao:\"em revisão\"}; pontos=-1 -> {faixa:\"revisar\", situacao:\"inválida\"}; pontos=100 -> {faixa:\"aprovar\", situacao:\"liberada\"}"],"assessmentEnvironment":"javascript","autoTested":true},"assessment":{"environment":"javascript","version":1,"checks":["behavior"],"testPath":"__devpath_tests__.js","referenceDir":"solutions/03.10","sourceTestPath":"tests/03.10.test.js","tests":"import { resumirNota } from \"./main.js\";\n\ndescribe(\"resumirNota: uma escolha curta e uma decisão com três faixas\", () => {\n  test(\"usa o limite de aprovação sem perder o caso exato de 60\", () => {\n    expect(resumirNota(60)).toEqual({ faixa: \"aprovar\", situacao: \"liberada\" });\n    expect(resumirNota(59)).toEqual({ faixa: \"revisar\", situacao: \"em revisão\" });\n  });\n\n  test(\"distingue nota inválida, zero, aprovação e limite máximo\", () => {\n    expect(resumirNota(-1)).toEqual({ faixa: \"revisar\", situacao: \"inválida\" });\n    expect(resumirNota(0)).toEqual({ faixa: \"revisar\", situacao: \"em revisão\" });\n    expect(resumirNota(100)).toEqual({ faixa: \"aprovar\", situacao: \"liberada\" });\n  });\n});\n"},"reference":[{"path":"main.js","content":"export function resumirNota(pontos) {\n  const faixa = pontos >= 60 ? \"aprovar\" : \"revisar\";\n  let situacao = \"\";\n\n  if (pontos < 0) {\n    situacao = \"inválida\";\n  } else if (pontos < 60) {\n    situacao = \"em revisão\";\n  } else {\n    situacao = \"liberada\";\n  }\n\n  return { faixa, situacao };\n}\n"}]},{"item":{"id":"04.11","title":"Validar percentual","stage":"04","kind":"MAKE","contentVersion":1,"optional":false,"duration":"18 min","runtime":"Node.js 24 LTS · ECMAScript 2026 · módulos ES","compatibility":"Sintaxe e classes de erro padrão do Node.js 24 LTS; sem dependências externas.","objective":"Classifique texto, -1, 0, 25, 100, 101 e NaN como TypeError, RangeError ou retorno.","prompt":"Implemente validarPercentual(valor). Exija Number finito entre 0 e 100, inclusive. Use TypeError se o argumento não for Number e RangeError se o número for não finito ou estiver fora da faixa. Retorne o percentual válido sem conversão.","firstResponse":{"action":"Classifique texto, -1, 0, 25, 100, 101 e NaN como TypeError, RangeError ou retorno.","timing":"Antes de executar ou abrir a solução."},"explanation":{"mental_model":"Uma função pode devolver um resultado quando o contrato é válido e lançar um erro quando não consegue cumprir esse contrato.","worked_example":"validarPercentual(25) devolve 25. Uma guard clause rejeita texto antes das comparações; depois, finitude e faixa são verificadas antes do retorno.","common_trap":"Comparações com NaN não indicam uma faixa válida e podem passar despercebidas sem Number.isFinite.","why_it_matters":"Validar na fronteira protege cálculos e informa ao chamador se o problema é o tipo ou o domínio do valor."},"interaction":"Editor de main.js com tabela de entrada, classe de erro ou valor retornado; execute os limites depois da previsão. Todos os controles funcionam por teclado.","resources":["Starter main.js com a assinatura exportada validarPercentual.","Contrato de entradas, limites inclusivos e classes de erro no enunciado.","MDN Error: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Error. Seção: Error types. Quando TypeError e RangeError descrevem causas diferentes?"],"starterFiles":[{"path":"main.js","content":"export function validarPercentual(valor) {}\n"}],"assets":[],"examples":[{"given":"validarPercentual(25)","expected":"25; validarPercentual(0) -> 0; validarPercentual(100) -> 100"}],"checks":[{"fixture":{"given":"validarPercentual(25)","expected":"25; validarPercentual(0) -> 0; validarPercentual(100) -> 100"},"scoring":"Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."}],"constraints":[],"rubric":["Usa guard clauses e lança TypeError quando o argumento não é Number.","Lança RangeError para não finito ou fora de 0..100 e devolve sem conversão os valores válidos, inclusive os limites.","Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."],"learningMetadata":{"requires":["04.07"]},"edgeCases":["validarPercentual(\"25\") -> TypeError; validarPercentual(-1) -> RangeError; validarPercentual(101) -> RangeError; validarPercentual(NaN) -> RangeError; validarPercentual(Infinity) -> RangeError"],"primers":["`export function validarPercentual(...)` deixa a função disponível ao avaliador; preserve `export` e a assinatura que o starter já apresenta.","`throw new TypeError('mensagem')` encerra a chamada e entrega o erro ao chamador. TypeError descreve um tipo incompatível; RangeError descreve um Number fora da faixa permitida. Uma guard clause valida primeiro e retorna ou lança antes do cálculo principal."],"review":{"prompt":"Qual erro descreve 101 quando a faixa permitida é de 0 a 100?","choices":["TypeError, pois todo valor rejeitado tem tipo incorreto.","RangeError, pois o tipo é Number mas o valor está fora da faixa.","Não lance erro; limite o resultado a 100."],"answer":1,"correctFeedback":"Isso mesmo: Number é o tipo certo, mas 101 não pertence ao domínio permitido.","incorrectFeedback":"TypeError descreve um tipo incompatível; RangeError descreve um valor de tipo correto que está fora do domínio."},"assessmentEnvironment":"javascript","autoTested":true,"preparation":{"guided":true,"stageTitle":"FUNÇÕES, RETORNO E ERROS","introduction":"Classifique texto, -1, 0, 25, 100, 101 e NaN como TypeError, RangeError ou retorno.","explanation":"Uma função pode devolver um resultado quando o contrato é válido e lançar um erro quando não consegue cumprir esse contrato.","conceptSteps":["Uma função pode devolver um resultado quando o contrato é válido e lançar um erro quando não consegue cumprir esse contrato.","Validar na fronteira protege cálculos e informa ao chamador se o problema é o tipo ou o domínio do valor."],"vocabulary":[],"workedExample":{"steps":["validarPercentual(25) devolve 25.","Uma guard clause rejeita texto antes das comparações; depois, finitude e faixa são verificadas antes do retorno."]},"notes":["Comparações com NaN não indicam uma faixa válida e podem passar despercebidas sem Number.isFinite.","Validar na fronteira protege cálculos e informa ao chamador se o problema é o tipo ou o domínio do valor."],"docs":[{"title":"MDN Error","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Error","section":"Error types","question":"Quando TypeError e RangeError descrevem causas diferentes?"}],"materials":["Starter main.js com a assinatura exportada validarPercentual.","Contrato de entradas, limites inclusivos e classes de erro no enunciado."],"predictionGuide":"Classifique texto, -1, 0, 25, 100, 101 e NaN como TypeError, RangeError ou retorno. Antes de executar ou abrir a solução.","practiceSteps":["Implemente validarPercentual(valor).","Exija Number finito entre 0 e 100, inclusive.","Use TypeError se o argumento não for Number e RangeError se o número for não finito ou estiver fora da faixa."],"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente validarPercentual(valor). Exija Number finito entre 0 e 100, inclusive. Use TypeError se o argumento não for Number e RangeError se o número for não finito ou estiver fora da faixa. Retorne o percentual válido sem conversão.","Compare com o exemplo público — dado: validarPercentual(25). Esperado: 25; validarPercentual(0) -> 0; validarPercentual(100) -> 100.","Cuidado com a armadilha desta atividade: Comparações com NaN não indicam uma faixa válida e podem passar despercebidas sem Number.isFinite."],"reflectionPrompt":"Compare sua primeira resposta com o resultado da tentativa. Explique a regra que você praticou e um erro que ela ajuda a evitar."},"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente validarPercentual(valor). Exija Number finito entre 0 e 100, inclusive. Use TypeError se o argumento não for Number e RangeError se o número for não finito ou estiver fora da faixa. Retorne o percentual válido sem conversão.","Compare com o exemplo público — dado: validarPercentual(25). Esperado: 25; validarPercentual(0) -> 0; validarPercentual(100) -> 100.","Cuidado com a armadilha desta atividade: Comparações com NaN não indicam uma faixa válida e podem passar despercebidas sem Number.isFinite."]},"assessment":{"environment":"javascript","version":1,"checks":["behavior"],"testPath":"__devpath_tests__.js","referenceDir":"solutions/04.11","sourceTestPath":"tests/04.11.test.js","tests":"import {validarPercentual} from './main.js';\n\ndescribe('validarPercentual', () => {\n  test('retorna percentuais válidos, inclusive os limites', () => {\n    expect(validarPercentual(25)).toBe(25);\n    expect(validarPercentual(0)).toBe(0);\n    expect(validarPercentual(100)).toBe(100);\n  });\n\n  test('distingue tipo incorreto de valor fora da faixa', () => {\n    expect(() => validarPercentual('25')).toThrow(TypeError);\n    for (const valor of [-1, 101, NaN, Infinity]) {\n      expect(() => validarPercentual(valor)).toThrow(RangeError);\n    }\n  });\n});\n"},"reference":[{"path":"main.js","content":"export function validarPercentual(valor) {\n  if (typeof valor !== 'number') throw new TypeError('percentual deve ser Number');\n  if (!Number.isFinite(valor) || valor < 0 || valor > 100) {\n    throw new RangeError('percentual fora de 0 a 100');\n  }\n  return valor;\n}\n"}]},{"item":{"id":"04.12","title":"Falha com contexto e limpeza","stage":"04","kind":"MAKE","contentVersion":1,"optional":false,"duration":"20 min","runtime":"Node.js 24 LTS · ECMAScript 2026 · módulos ES","compatibility":"Error, try/catch/finally e JSON.parse disponíveis no Node.js 24 LTS.","objective":"Trace o caminho de sucesso, o SyntaxError do parse e um erro de leitura; marque quando liberar roda.","prompt":"Implemente lerJsonSeguro(ler, liberar). Chame ler() e interprete o texto com JSON.parse. Se ocorrer SyntaxError, lance new Error com a mensagem 'JSON inválido: ' seguida da mensagem original. Se ler() lançar outro erro, relance o mesmo objeto. Chame liberar() exatamente uma vez em finally, tanto no sucesso como na falha. O contrato considera que liberar() conclui sem lançar; falha própria da limpeza fica fora desta atividade.","firstResponse":{"action":"Trace o caminho de sucesso, o SyntaxError do parse e um erro de leitura; marque quando liberar roda.","timing":"Antes de executar ou abrir a solução."},"explanation":{"mental_model":"try/catch/finally separa operação, tratamento de uma falha conhecida e limpeza que precisa ocorrer em todos os caminhos.","worked_example":"ler e liberar são funções recebidas como argumentos e chamadas dentro da operação. Se JSON.parse falhar com SyntaxError, o catch pode lançar Error com mensagem de contexto; finally roda antes de a função terminar, mesmo quando há throw.","common_trap":"Um catch amplo que retorna {} trata entrada inválida como sucesso e pode também esconder uma falha do leitor.","why_it_matters":"Recursos como arquivos, conexões e cursores precisam ser liberados mesmo quando leitura ou interpretação falha."},"interaction":"Editor com três trilhas de execução e contagem visível de chamadas a liberar; execute sucesso e cada falha depois de prever. A navegação é acessível por teclado.","resources":["Starter main.js com as funções ler e liberar recebidas e chamadas pela função principal.","Contrato de contextualização da sintaxe, identidade de outros erros e limpeza no enunciado.","MDN try catch: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/try...catch. Seção: The finally block. Por que finally roda quando o bloco try lança?"],"starterFiles":[{"path":"main.js","content":"export function lerJsonSeguro(ler, liberar) {}\n"}],"assets":[],"examples":[{"given":"lerJsonSeguro(()=>'{}',()=>{})","expected":"{}"}],"checks":[{"fixture":{"given":"lerJsonSeguro(()=>'{}',()=>{})","expected":"{}"},"scoring":"Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."}],"constraints":[],"rubric":["Transforma apenas SyntaxError em Error com mensagem contextualizada e relança o erro de leitura original.","Retorna o objeto parseado no sucesso e chama liberar exatamente uma vez em todos os caminhos.","Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."],"learningMetadata":{"requires":["04.11"]},"edgeCases":["JSON inválido -> Error com mensagem de contexto; erro de ler() -> mesmo erro original; liberar() é chamado uma vez em sucesso ou falha"],"primers":["`export function nome(...)` mantém a função importável pelo avaliador; preserve `export` e os parâmetros do starter.","`JSON.parse(texto)` transforma texto JSON em valor JavaScript; texto malformado lança SyntaxError. A expressão `erro instanceof SyntaxError` identifica essa classe para contextualizá-la.","A forma é `try { operação } catch (erro) { tratamento } finally { limpeza }`. catch recebe o erro lançado no try; finally executa antes do retorno ou da propagação do erro. Deixe return e throw fora de finally para não substituir o resultado nem esconder a falha original.","`ler` e `liberar` são funções recebidas como argumentos: a primeira é chamada para obter o texto, a segunda para limpar o recurso em todos os caminhos."],"review":{"prompt":"Qual bloco garante a limpeza se o parse ou a leitura lançar?","choices":["catch, que só roda quando uma exceção ocorre.","return, que encerra o try antes da limpeza.","finally, que executa antes da saída normal ou excepcional."],"answer":2,"correctFeedback":"Correto: finally é o lugar para a limpeza que não depende do resultado.","incorrectFeedback":"catch roda apenas em falhas; finally roda depois do sucesso ou da falha, antes da saída."},"assessmentEnvironment":"javascript","autoTested":true,"preparation":{"guided":true,"stageTitle":"FUNÇÕES, RETORNO E ERROS","introduction":"Trace o caminho de sucesso, o SyntaxError do parse e um erro de leitura; marque quando liberar roda.","explanation":"try/catch/finally separa operação, tratamento de uma falha conhecida e limpeza que precisa ocorrer em todos os caminhos.","conceptSteps":["try/catch/finally separa operação, tratamento de uma falha conhecida e limpeza que precisa ocorrer em todos os caminhos.","Recursos como arquivos, conexões e cursores precisam ser liberados mesmo quando leitura ou interpretação falha."],"vocabulary":[],"workedExample":{"steps":["ler e liberar são funções recebidas como argumentos e chamadas dentro da operação.","Se JSON.parse falhar com SyntaxError, o catch pode lançar Error com mensagem de contexto; finally roda antes de a função terminar, mesmo quando há throw."]},"notes":["Um catch amplo que retorna {} trata entrada inválida como sucesso e pode também esconder uma falha do leitor.","Recursos como arquivos, conexões e cursores precisam ser liberados mesmo quando leitura ou interpretação falha."],"docs":[{"title":"MDN try catch","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/try...catch","section":"The finally block","question":"Por que finally roda quando o bloco try lança?"}],"materials":["Starter main.js com as funções ler e liberar recebidas e chamadas pela função principal.","Contrato de contextualização da sintaxe, identidade de outros erros e limpeza no enunciado."],"predictionGuide":"Trace o caminho de sucesso, o SyntaxError do parse e um erro de leitura; marque quando liberar roda. Antes de executar ou abrir a solução.","practiceSteps":["Implemente lerJsonSeguro(ler, liberar).","Chame ler() e interprete o texto com JSON.parse.","Se ocorrer SyntaxError, lance new Error com a mensagem 'JSON inválido: ' seguida da mensagem original."],"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente lerJsonSeguro(ler, liberar). Chame ler() e interprete o texto com JSON.parse. Se ocorrer SyntaxError, lance new Error com a mensagem 'JSON inválido: ' seguida da mensagem original. Se ler() lançar outro erro, relance o mesmo obje","Compare com o exemplo público — dado: lerJsonSeguro(()=>'{}',()=>{}). Esperado: {}.","Cuidado com a armadilha desta atividade: Um catch amplo que retorna {} trata entrada inválida como sucesso e pode também esconder uma falha do leitor."],"reflectionPrompt":"Compare sua primeira resposta com o resultado da tentativa. Explique a regra que você praticou e um erro que ela ajuda a evitar."},"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente lerJsonSeguro(ler, liberar). Chame ler() e interprete o texto com JSON.parse. Se ocorrer SyntaxError, lance new Error com a mensagem 'JSON inválido: ' seguida da mensagem original. Se ler() lançar outro erro, relance o mesmo obje","Compare com o exemplo público — dado: lerJsonSeguro(()=>'{}',()=>{}). Esperado: {}.","Cuidado com a armadilha desta atividade: Um catch amplo que retorna {} trata entrada inválida como sucesso e pode também esconder uma falha do leitor."]},"assessment":{"environment":"javascript","version":1,"checks":["behavior"],"testPath":"__devpath_tests__.js","referenceDir":"solutions/04.12","sourceTestPath":"tests/04.12.test.js","tests":"import {lerJsonSeguro} from './main.js';\n\ndescribe('lerJsonSeguro', () => {\n  test('interpreta JSON válido e libera o recurso uma vez', () => {\n    let liberacoes = 0;\n    expect(lerJsonSeguro(() => '{\"ativo\":true}', () => liberacoes++)).toEqual({ativo: true});\n    expect(liberacoes).toBe(1);\n  });\n\n  test('acrescenta contexto à sintaxe inválida e sempre libera', () => {\n    let liberacoes = 0;\n    let mensagemOriginal;\n    try { JSON.parse('{'); } catch (erro) { mensagemOriginal = erro.message; }\n    let recebido;\n    try { lerJsonSeguro(() => '{', () => liberacoes++); } catch (error) { recebido = error; }\n    expect(recebido).toBeInstanceOf(Error);\n    expect(recebido.message).toBe(`JSON inválido: ${mensagemOriginal}`);\n    expect(liberacoes).toBe(1);\n  });\n\n  test('preserva erro de leitura e libera mesmo quando ela falha', () => {\n    const falha = new Error('disco indisponível');\n    let liberacoes = 0;\n    let recebido;\n    try { lerJsonSeguro(() => { throw falha; }, () => liberacoes++); } catch (error) { recebido = error; }\n    expect(recebido).toBe(falha);\n    expect(liberacoes).toBe(1);\n  });\n});\n"},"reference":[{"path":"main.js","content":"export function lerJsonSeguro(ler, liberar) {\n  try {\n    return JSON.parse(ler());\n  } catch (erro) {\n    if (!(erro instanceof SyntaxError)) throw erro;\n    throw new Error(`JSON inválido: ${erro.message}`);\n  } finally {\n    liberar();\n  }\n}\n"}]},{"item":{"id":"04.13","title":"Retorno esperado ou erro","stage":"04","kind":"MAKE","contentVersion":1,"optional":false,"duration":"16 min","runtime":"Node.js 24 LTS · ECMAScript 2026 · módulos ES","compatibility":"Array.isArray e classes de erro padrão disponíveis no Node.js 24 LTS; sem dependências externas.","objective":"Classifique cada entrada como taxa, null esperado ou TypeError por argumento inválido.","prompt":"Implemente taxaDeEntrega(tipo). Exija string não vazia com TypeError para chamada inválida. Retorne 0.1 para 'comum', 0.25 para 'expressa' e null para qualquer outra opção bem formada ainda não cadastrada.","firstResponse":{"action":"Classifique cada entrada como taxa, null esperado ou TypeError por argumento inválido.","timing":"Antes de executar ou abrir a solução."},"explanation":{"mental_model":"Ausência esperada pode ser representada por um valor de retorno; erro indica que a chamada não respeitou o contrato ou que a operação não pôde ser concluída.","worked_example":"A string 'comum' devolve 0.1 e 'expressa' devolve 0.25. Uma modalidade futura como 'noturna' retorna null; um argumento que não é string não cumpre a API e lança TypeError.","common_trap":"Lançar para toda opção desconhecida força o chamador a tratar uma possibilidade comum como exceção; retornar null para argumentos inválidos mascara erro de programação.","why_it_matters":"Uma API previsível permite que o chamador trate resultados opcionais com um ramo normal e reserve exceções para falhas reais."},"interaction":"Editor de main.js e tabela de decisão para valor retornado, null e TypeError; depois execute opções conhecidas, ausência e entradas inválidas. Todos os controles são acessíveis por teclado.","resources":["Starter main.js com a assinatura exportada taxaDeEntrega.","Contrato de strings permitidas, valores de taxa e resultado de ausência no enunciado.","MDN throw: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/throw. Seção: Description. Como uma função informa uma entrada inválida ao chamador?"],"starterFiles":[{"path":"main.js","content":"export function taxaDeEntrega(tipo) {}\n"}],"assets":[],"examples":[{"given":"taxaDeEntrega('comum')","expected":"0.1; taxaDeEntrega('expressa') -> 0.25; taxaDeEntrega('noturna') -> null"}],"checks":[{"fixture":{"given":"taxaDeEntrega('comum')","expected":"0.1; taxaDeEntrega('expressa') -> 0.25; taxaDeEntrega('noturna') -> null"},"scoring":"Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."}],"constraints":[],"rubric":["Valida tipo e string não vazia com guard clauses e lança TypeError quando a chamada viola o contrato.","Retorna 0.1 e 0.25 para as opções cadastradas e null para opção válida sem cadastro.","Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."],"learningMetadata":{"requires":["04.12"]},"edgeCases":["taxaDeEntrega('') -> TypeError; taxaDeEntrega(4) -> TypeError; opção não cadastrada e não vazia -> null"],"primers":["`export function taxaDeEntrega(...)` deixa a função disponível ao avaliador; preserve `export` e a assinatura do starter.","Uma guard clause rejeita argumento inválido antes das decisões normais. Use `throw new TypeError('mensagem')` quando a chamada viola o contrato; retorne null quando a opção está bem formada, mas não tem resultado cadastrado."],"review":{"prompt":"O que deve ocorrer quando a modalidade é uma string não vazia ainda não cadastrada?","choices":["Retornar null, pois a ausência é resultado esperado da consulta.","Lançar TypeError, pois nenhuma taxa foi cadastrada.","Retornar a taxa comum como padrão."],"answer":0,"correctFeedback":"Isso mesmo: null comunica ausência sem tratar uma consulta válida como falha excepcional.","incorrectFeedback":"O chamador forneceu argumento válido; uma opção desconhecida segue o contrato normal e retorna null."},"assessmentEnvironment":"javascript","autoTested":true,"preparation":{"guided":true,"stageTitle":"FUNÇÕES, RETORNO E ERROS","introduction":"Classifique cada entrada como taxa, null esperado ou TypeError por argumento inválido.","explanation":"Ausência esperada pode ser representada por um valor de retorno; erro indica que a chamada não respeitou o contrato ou que a operação não pôde ser concluída.","conceptSteps":["Ausência esperada pode ser representada por um valor de retorno; erro indica que a chamada não respeitou o contrato ou que a operação não pôde ser concluída.","Uma API previsível permite que o chamador trate resultados opcionais com um ramo normal e reserve exceções para falhas reais."],"vocabulary":[],"workedExample":{"steps":["A string 'comum' devolve 0.1 e 'expressa' devolve 0.25.","Uma modalidade futura como 'noturna' retorna null; um argumento que não é string não cumpre a API e lança TypeError."]},"notes":["Lançar para toda opção desconhecida força o chamador a tratar uma possibilidade comum como exceção; retornar null para argumentos inválidos mascara erro de programação.","Uma API previsível permite que o chamador trate resultados opcionais com um ramo normal e reserve exceções para falhas reais."],"docs":[{"title":"MDN throw","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/throw","section":"Description","question":"Como uma função informa uma entrada inválida ao chamador?"}],"materials":["Starter main.js com a assinatura exportada taxaDeEntrega.","Contrato de strings permitidas, valores de taxa e resultado de ausência no enunciado."],"predictionGuide":"Classifique cada entrada como taxa, null esperado ou TypeError por argumento inválido. Antes de executar ou abrir a solução.","practiceSteps":["Implemente taxaDeEntrega(tipo).","Exija string não vazia com TypeError para chamada inválida.","Retorne 0.1 para 'comum', 0.25 para 'expressa' e null para qualquer outra opção bem formada ainda não cadastrada."],"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente taxaDeEntrega(tipo). Exija string não vazia com TypeError para chamada inválida. Retorne 0.1 para 'comum', 0.25 para 'expressa' e null para qualquer outra opção bem formada ainda não cadastrada.","Compare com o exemplo público — dado: taxaDeEntrega('comum'). Esperado: 0.1; taxaDeEntrega('expressa') -> 0.25; taxaDeEntrega('noturna') -> null.","Cuidado com a armadilha desta atividade: Lançar para toda opção desconhecida força o chamador a tratar uma possibilidade comum como exceção; retornar null para argumentos inválidos mascara erro de programação."],"reflectionPrompt":"Compare sua primeira resposta com o resultado da tentativa. Explique a regra que você praticou e um erro que ela ajuda a evitar."},"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente taxaDeEntrega(tipo). Exija string não vazia com TypeError para chamada inválida. Retorne 0.1 para 'comum', 0.25 para 'expressa' e null para qualquer outra opção bem formada ainda não cadastrada.","Compare com o exemplo público — dado: taxaDeEntrega('comum'). Esperado: 0.1; taxaDeEntrega('expressa') -> 0.25; taxaDeEntrega('noturna') -> null.","Cuidado com a armadilha desta atividade: Lançar para toda opção desconhecida força o chamador a tratar uma possibilidade comum como exceção; retornar null para argumentos inválidos mascara erro de programação."]},"assessment":{"environment":"javascript","version":1,"checks":["behavior"],"testPath":"__devpath_tests__.js","referenceDir":"solutions/04.13","sourceTestPath":"tests/04.13.test.js","tests":"import {taxaDeEntrega} from './main.js';\n\ndescribe('taxaDeEntrega', () => {\n  test('retorna a taxa das opções conhecidas', () => {\n    expect(taxaDeEntrega('comum')).toBe(0.1);\n    expect(taxaDeEntrega('expressa')).toBe(0.25);\n  });\n\n  test('retorna null para opção desconhecida e lança para argumento inválido', () => {\n    expect(taxaDeEntrega('noturna')).toBe(null);\n    expect(() => taxaDeEntrega('')).toThrow(TypeError);\n    expect(() => taxaDeEntrega(4)).toThrow(TypeError);\n  });\n});\n"},"reference":[{"path":"main.js","content":"export function taxaDeEntrega(tipo) {\n  if (typeof tipo !== 'string' || tipo.trim() === '') {\n    throw new TypeError('tipo deve ser uma string não vazia');\n  }\n  if (tipo === 'comum') return 0.1;\n  if (tipo === 'expressa') return 0.25;\n  return null;\n}\n"}]},{"item":{"id":"06.11","title":"Acessos opcionais e padrões precisos","stage":"06","kind":"MAKE","contentVersion":1,"optional":false,"duration":"20 min","runtime":"Node.js 24 LTS · ECMAScript 2026 · módulos ES","compatibility":"Optional chaining e nullish coalescing fazem parte do JavaScript padrão no Node.js 24 LTS; sem dependências externas.","objective":"Preveja o resultado para usuario ausente e para perfil com 0, false, \"\" e tipo inválido antes de executar.","prompt":"Implemente resumirPerfil(usuario) com acesso opcional ao objeto perfil. Se perfil estiver presente, valide que seja um objeto não-array; retorne null para outro tipo. Quando cada campo estiver ausente/null, use nome:\"Visitante\", pontos:100, ativo:true e mensagem:\"Sem mensagem\". Uma configuração pode ser 0, false ou \"\"; conserve esses valores, aplicando padrão somente a null/undefined.","firstResponse":{"action":"Preveja o resultado para usuario ausente e para perfil com 0, false, \"\" e tipo inválido antes de executar.","timing":"Depois de ler o exemplo e o primer de função exportada, antes de executar ou pedir dica."},"explanation":{"mental_model":"Optional chaining `obj?.campo` interrompe o acesso quando obj é null ou undefined e devolve undefined. Nullish coalescing `valor ?? padrao` usa o padrão apenas para null ou undefined; 0, false e \"\" continuam sendo valores presentes. Esses operadores não validam se o valor tem o tipo esperado.","worked_example":"Em `config?.som?.volume ?? 5`, caminho ausente produz 5, mas volume=0 permanece 0. Do mesmo modo, `config?.avisos?.ativo ?? true` conserva false. Um guard clause separado confere o tipo de `config` antes de ler suas propriedades.","common_trap":"`||` escolhe o padrão para qualquer valor falsy, incluindo 0, false e \"\"; `?.` evita erro de acesso quando algo é nullish, mas não confirma que o valor é um objeto válido.","why_it_matters":"Preferências e dados recebidos podem omitir ramos inteiros; valores falsy também podem representar escolhas válidas do usuário."},"interaction":"Edite o código e compare cada campo retornado. Os testes automáticos conferem ausência, valores falsy e perfil inválido; o uso de ?. e ?? é conferido por você na autoavaliação.","resources":["MDN Optional chaining: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Optional_chaining","MDN Nullish coalescing: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Nullish_coalescing"],"starterFiles":[{"path":"main.js","content":"export function resumirPerfil(usuario) {\n  const perfil = usuario?.perfil;\n  if (perfil !== null && perfil !== undefined && (typeof perfil !== \"object\" || Array.isArray(perfil))) {\n    // Retorne null para um contêiner presente que não seja um registro.\n  }\n  return {\n    nome: \"\",\n    pontos: 0,\n    ativo: false,\n    mensagem: \"\",\n  };\n}\n"}],"assets":[],"examples":[{"given":"usuario={perfil:{nome:\"Ana\",pontos:0,ativo:false,mensagem:\"\"}}","expected":"{nome:\"Ana\",pontos:0,ativo:false,mensagem:\"\"}"}],"checks":[{"fixture":{"given":"usuario={perfil:{nome:\"Ana\",pontos:0,ativo:false,mensagem:\"\"}}","expected":"{nome:\"Ana\",pontos:0,ativo:false,mensagem:\"\"}"},"scoring":"Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."}],"constraints":["Não use encadeamentos com && para acessar perfil.","Não use || para aplicar os padrões.","Perfil ausente/null é permitido; perfil presente deve ser objeto não-array, senão retorne null.","A função deve retornar as quatro propriedades no contrato quando perfil for válido."],"rubric":["Encadeamento ?. protege usuario, perfil e cada leitura opcional.","?? aplica cada valor padrão somente a null/undefined.","A saída preserva 0, false e string vazia.","Uma guard clause retorna null para perfil que não é registro; ?. não substitui validação.","Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."],"learningMetadata":{"requires":["06.10"]},"edgeCases":["usuario=null -> {nome:\"Visitante\",pontos:100,ativo:true,mensagem:\"Sem mensagem\"}; usuario={perfil:{}} -> mesmos padrões; pontos=undefined usa 100, mas pontos=0 permanece 0; perfil=\"inválido\" ou [] -> null"],"primers":["`export function resumirPerfil(usuario)` é o invólucro pronto para que o avaliador importe a função; preserve `export`, o nome e o parâmetro e implemente o retorno pedido. Módulos são aprofundados na etapa 14."],"review":{"prompt":"Qual expressão fornece um padrão quando pontos é 0, preservando esse zero?","choices":["pontos || 100","pontos ?? 100","pontos && 100"],"answer":1,"correctFeedback":"Correto: ?? troca somente null e undefined; zero é mantido.","incorrectFeedback":"|| considera 0 falsy e o substituiria; && também não é operador de padrão."},"assessmentEnvironment":"javascript","autoTested":true,"preparation":{"guided":true,"stageTitle":"OBJETOS E REFERÊNCIAS","introduction":"Preveja o resultado para usuario ausente e para perfil com 0, false, \"\" e tipo inválido antes de executar.","explanation":"Optional chaining `obj?.campo` interrompe o acesso quando obj é null ou undefined e devolve undefined. Nullish coalescing `valor ?? padrao` usa o padrão apenas para null ou undefined; 0, false e \"\" continuam sendo valores presentes. Esses operadores não validam se o valor tem o tipo esperado.","conceptSteps":["Optional chaining `obj?.campo` interrompe o acesso quando obj é null ou undefined e devolve undefined.","Nullish coalescing `valor ?? padrao` usa o padrão apenas para null ou undefined; 0, false e \"\" continuam sendo valores presentes.","Esses operadores não validam se o valor tem o tipo esperado.","Preferências e dados recebidos podem omitir ramos inteiros; valores falsy também podem representar escolhas válidas do usuário."],"vocabulary":["`config` — Um guard clause separado confere o tipo de `config` antes de ler suas propriedades."],"workedExample":{"steps":["Em `config?.som?.volume ?? 5`, caminho ausente produz 5, mas volume=0 permanece 0.","Do mesmo modo, `config?.avisos?.ativo ?? true` conserva false.","Um guard clause separado confere o tipo de `config` antes de ler suas propriedades."]},"notes":["`||` escolhe o padrão para qualquer valor falsy, incluindo 0, false e \"\"; `?.` evita erro de acesso quando algo é nullish, mas não confirma que o valor é um objeto válido.","Preferências e dados recebidos podem omitir ramos inteiros; valores falsy também podem representar escolhas válidas do usuário."],"docs":[{"title":"MDN Optional chaining","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Optional_chaining","section":"","question":""},{"title":"MDN Nullish coalescing","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Nullish_coalescing","section":"","question":""}],"materials":[],"predictionGuide":"Preveja o resultado para usuario ausente e para perfil com 0, false, \"\" e tipo inválido antes de executar. Depois de ler o exemplo e o primer de função exportada, antes de executar ou pedir dica.","practiceSteps":["Implemente resumirPerfil(usuario) com acesso opcional ao objeto perfil.","Se perfil estiver presente, valide que seja um objeto não-array; retorne null para outro tipo.","Quando cada campo estiver ausente/null, use nome:\"Visitante\", pontos:100, ativo:true e mensagem:\"Sem mensagem\".","Restrição: Não use encadeamentos com && para acessar perfil.","Restrição: Não use || para aplicar os padrões."],"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente resumirPerfil(usuario) com acesso opcional ao objeto perfil. Se perfil estiver presente, valide que seja um objeto não-array; retorne null para outro tipo. Quando cada campo estiver ausente/null, use nome:\"Visitante\", pontos:100,","Compare com o exemplo público — dado: usuario={perfil:{nome:\"Ana\",pontos:0,ativo:false,mensagem:\"\"}}. Esperado: {nome:\"Ana\",pontos:0,ativo:false,mensagem:\"\"}.","Cuidado com a armadilha desta atividade: `||` escolhe o padrão para qualquer valor falsy, incluindo 0, false e \"\"; `?.` evita erro de acesso quando algo é nullish, mas não confirma que o valor é um objeto válido."],"reflectionPrompt":"Compare sua primeira resposta com o resultado da tentativa. Explique a regra que você praticou e um erro que ela ajuda a evitar."},"hints":["Releia o enunciado e separe entrada, saída e restrições: Implemente resumirPerfil(usuario) com acesso opcional ao objeto perfil. Se perfil estiver presente, valide que seja um objeto não-array; retorne null para outro tipo. Quando cada campo estiver ausente/null, use nome:\"Visitante\", pontos:100,","Compare com o exemplo público — dado: usuario={perfil:{nome:\"Ana\",pontos:0,ativo:false,mensagem:\"\"}}. Esperado: {nome:\"Ana\",pontos:0,ativo:false,mensagem:\"\"}.","Cuidado com a armadilha desta atividade: `||` escolhe o padrão para qualquer valor falsy, incluindo 0, false e \"\"; `?.` evita erro de acesso quando algo é nullish, mas não confirma que o valor é um objeto válido."]},"assessment":{"environment":"javascript","version":1,"checks":["behavior"],"testPath":"__devpath_tests__.js","referenceDir":"solutions/06.11","sourceTestPath":"tests/06.11.test.js","tests":"import { resumirPerfil } from \"./main.js\";\n\ndescribe(\"resumirPerfil: acesso opcional e padrão nullish\", () => {\n  test(\"aplica padrões para usuário ou perfil ausentes\", () => {\n    const padrao = { nome: \"Visitante\", pontos: 100, ativo: true, mensagem: \"Sem mensagem\" };\n    expect(resumirPerfil(undefined)).toEqual(padrao);\n    expect(resumirPerfil(null)).toEqual(padrao);\n    expect(resumirPerfil({})).toEqual(padrao);\n    expect(resumirPerfil({ perfil: null })).toEqual(padrao);\n  });\n\n  test(\"preserva zero, false e string vazia\", () => {\n    expect(resumirPerfil({ perfil: { nome: \"Ana\", pontos: 0, ativo: false, mensagem: \"\" } }))\n      .toEqual({ nome: \"Ana\", pontos: 0, ativo: false, mensagem: \"\" });\n  });\n\n  test(\"usa o padrão quando uma propriedade é explicitamente null ou undefined\", () => {\n    expect(resumirPerfil({ perfil: { nome: undefined, pontos: null, ativo: undefined, mensagem: null } }))\n      .toEqual({ nome: \"Visitante\", pontos: 100, ativo: true, mensagem: \"Sem mensagem\" });\n  });\n\n  test(\"?. não valida o tipo do contêiner: uma guard clause rejeita texto e array\", () => {\n    expect(resumirPerfil({ perfil: \"inválido\" })).toBeNull();\n    expect(resumirPerfil({ perfil: [] })).toBeNull();\n  });\n});\n"},"reference":[{"path":"main.js","content":"export function resumirPerfil(usuario) {\n  const perfil = usuario?.perfil;\n  if (perfil !== null && perfil !== undefined && (typeof perfil !== \"object\" || Array.isArray(perfil))) {\n    return null;\n  }\n  return {\n    nome: usuario?.perfil?.nome ?? \"Visitante\",\n    pontos: usuario?.perfil?.pontos ?? 100,\n    ativo: usuario?.perfil?.ativo ?? true,\n    mensagem: usuario?.perfil?.mensagem ?? \"Sem mensagem\",\n  };\n}\n"}]},{"item":{"id":"17.11","title":"Classes: visibilidade e propriedades apagáveis","stage":"17","kind":"PROJECT","contentVersion":1,"optional":false,"duration":"50 min","runtime":"TypeScript 7.0 strict · Node.js 24 LTS","compatibility":"A configuração do exercício usa `erasableSyntaxOnly: true`; o código não precisa de transformação para propriedades do constructor. `private` e `readonly` são estáticos; `#` tem privacidade runtime.","objective":"Classifique `private`, `#`, `readonly` e `implements` como checagem estática, runtime ou declaração estrutural; depois indique a forma de constructor compatível com erasableSyntaxOnly.","prompt":"Corrija as declarações da classe em main.ts: implemente Capacidade, torne limiteBytes private readonly e nome readonly. Preserve as propriedades explícitas e atribuições no constructor. Complete `podeGuardar` para aceitar bytes finitos entre zero e o limite, inclusive.","firstResponse":{"action":"Classifique `private`, `#`, `readonly` e `implements` como checagem estática, runtime ou declaração estrutural; depois indique a forma de constructor compatível com erasableSyntaxOnly.","timing":"3 min"},"explanation":{"mental_model":"`private` restringe acesso pelo TypeScript; `#campo` oferece privacidade do JavaScript em runtime. `readonly` bloqueia reatribuição na checagem, mas não congela o objeto. `implements` verifica o contrato estrutural da interface e não cria comportamento runtime.","worked_example":"Declare os campos no corpo da classe e faça `this.limiteBytes = limiteBytes` dentro do constructor. Com `erasableSyntaxOnly`, a remoção dos tipos não precisa transformar parameter properties.","common_trap":"`constructor(private limiteBytes: number)` declara e inicializa uma propriedade durante a transformação. `erasableSyntaxOnly` proíbe essa sintaxe que não pode ser apenas apagada.","why_it_matters":"Separar as garantias estáticas das garantias JavaScript ajuda a escolher encapsulamento sem prometer proteção que não existe em runtime."},"interaction":"Corrija as declarações, complete o método e execute entradas válidas e inválidas; os contratos protegidos verificam o uso pela interface. Alternativa acessível: use Tab e setas para percorrer o editor e os resultados.","resources":["TypeScript Handbook — Classes: https://www.typescriptlang.org/docs/handbook/2/classes.html","TypeScript TSConfig — erasableSyntaxOnly: https://www.typescriptlang.org/tsconfig/erasableSyntaxOnly.html"],"starterFiles":[{"path":"main.ts","content":"export interface Capacidade {\n  readonly nome: string;\n  podeGuardar(bytes: number): boolean;\n}\n\nexport class Plano {\n  limiteBytes: number;\n  nome: string;\n\n  constructor(nome: string, limiteBytes: number) {\n    this.nome = nome;\n    this.limiteBytes = limiteBytes;\n  }\n\n  podeGuardar(bytes: number): boolean {\n    // Implemente a regra sem acessar estado global.\n    return false;\n  }\n}\n"},{"path":"package.json","content":"{\"type\":\"module\"}\n"},{"path":"tsconfig.json","content":"{\n  \"compilerOptions\": {\n    \"target\": \"es2024\",\n    \"module\": \"nodenext\",\n    \"strict\": true,\n    \"erasableSyntaxOnly\": true,\n    \"verbatimModuleSyntax\": true,\n    \"allowImportingTsExtensions\": true,\n    \"noEmit\": true\n  }\n}\n"}],"assets":[],"examples":[{"given":"Plano('Básico',100).podeGuardar(60)","expected":"true; checagem rejeita acesso externo ao limite e reatribuição ao nome"}],"checks":[{"fixture":{"given":"Plano('Básico',100).podeGuardar(60)","expected":"true; checagem rejeita acesso externo ao limite e reatribuição ao nome"},"scoring":"Rode critérios comportamentais e revisão humana para decisões abertas."}],"constraints":[],"rubric":["Rode critérios comportamentais e revisão humana para decisões abertas."],"learningMetadata":{"requires":["15.01","17.02"]},"edgeCases":["bytes acima do limite, negativos, NaN e Infinity -> false; `constructor(private limiteBytes: number)` é parameter property e não passa erasableSyntaxOnly"],"review":{"prompt":"Qual declaração pode ser apagada sem transformação sob `erasableSyntaxOnly`?","choices":["`constructor(private campo: number)`","`constructor(readonly campo: number)`","`constructor(public campo: number)`","Campo explícito e atribuição `this.campo = campo` no constructor"],"answer":3,"correctFeedback":"Correto: a propriedade e a atribuição são JavaScript comum após apagar a anotação de tipo.","incorrectFeedback":"Parameter properties precisam emitir declaração e atribuição no corpo da classe."},"assessmentEnvironment":"typescript","autoTested":true,"preparation":{"guided":true,"stageTitle":"GENERICS E OVERLOADS","introduction":"Classifique `private`, `#`, `readonly` e `implements` como checagem estática, runtime ou declaração estrutural; depois indique a forma de constructor compatível com erasableSyntaxOnly.","explanation":"`private` restringe acesso pelo TypeScript; `#campo` oferece privacidade do JavaScript em runtime. `readonly` bloqueia reatribuição na checagem, mas não congela o objeto. `implements` verifica o contrato estrutural da interface e não cria comportamento runtime.","conceptSteps":["`private` restringe acesso pelo TypeScript; `#campo` oferece privacidade do JavaScript em runtime.","`readonly` bloqueia reatribuição na checagem, mas não congela o objeto.","`implements` verifica o contrato estrutural da interface e não cria comportamento runtime.","Separar as garantias estáticas das garantias JavaScript ajuda a escolher encapsulamento sem prometer proteção que não existe em runtime."],"vocabulary":["`private` — `private` restringe acesso pelo TypeScript; `#campo` oferece privacidade do JavaScript em runtime.","`readonly` — `readonly` bloqueia reatribuição na checagem, mas não congela o objeto.","`implements` — `implements` verifica o contrato estrutural da interface e não cria comportamento runtime.","`erasableSyntaxOnly` — Com `erasableSyntaxOnly`, a remoção dos tipos não precisa transformar parameter properties."],"workedExample":{"steps":["Declare os campos no corpo da classe e faça `this.limiteBytes = limiteBytes` dentro do constructor.","Com `erasableSyntaxOnly`, a remoção dos tipos não precisa transformar parameter properties."]},"notes":["`constructor(private limiteBytes: number)` declara e inicializa uma propriedade durante a transformação. `erasableSyntaxOnly` proíbe essa sintaxe que não pode ser apenas apagada.","Separar as garantias estáticas das garantias JavaScript ajuda a escolher encapsulamento sem prometer proteção que não existe em runtime."],"docs":[{"title":"TypeScript Handbook — Classes","url":"https://www.typescriptlang.org/docs/handbook/2/classes.html","section":"","question":""},{"title":"TypeScript TSConfig — erasableSyntaxOnly","url":"https://www.typescriptlang.org/tsconfig/erasableSyntaxOnly.html","section":"","question":""}],"materials":[],"predictionGuide":"Classifique `private`, `#`, `readonly` e `implements` como checagem estática, runtime ou declaração estrutural; depois indique a forma de constructor compatível com erasableSyntaxOnly. 3 min","practiceSteps":["Corrija as declarações da classe em main.ts: implemente Capacidade, torne limiteBytes private readonly e nome readonly.","Preserve as propriedades explícitas e atribuições no constructor.","Complete `podeGuardar` para aceitar bytes finitos entre zero e o limite, inclusive."],"hints":["Releia o enunciado e separe entrada, saída e restrições: Corrija as declarações da classe em main.ts: implemente Capacidade, torne limiteBytes private readonly e nome readonly. Preserve as propriedades explícitas e atribuições no constructor. Complete `podeGuardar` para aceitar bytes finitos entr","Compare com o exemplo público — dado: Plano('Básico',100).podeGuardar(60). Esperado: true; checagem rejeita acesso externo ao limite e reatribuição ao nome.","Cuidado com a armadilha desta atividade: `constructor(private limiteBytes: number)` declara e inicializa uma propriedade durante a transformação."],"reflectionPrompt":"Compare sua primeira resposta com o resultado da tentativa. Explique a regra que você praticou e um erro que ela ajuda a evitar."},"hints":["Releia o enunciado e separe entrada, saída e restrições: Corrija as declarações da classe em main.ts: implemente Capacidade, torne limiteBytes private readonly e nome readonly. Preserve as propriedades explícitas e atribuições no constructor. Complete `podeGuardar` para aceitar bytes finitos entr","Compare com o exemplo público — dado: Plano('Básico',100).podeGuardar(60). Esperado: true; checagem rejeita acesso externo ao limite e reatribuição ao nome.","Cuidado com a armadilha desta atividade: `constructor(private limiteBytes: number)` declara e inicializa uma propriedade durante a transformação."]},"assessment":{"environment":"typescript","version":1,"checks":["types","behavior","mutation"],"entryPath":"main.ts","tsconfigPath":"tsconfig.json","testPath":"__devpath_tests__.js","behaviorTestPath":"__devpath_protected_behavior__.js","referenceDir":"solutions/17.11","correctFiles":[{"path":"main.ts","content":"export interface Capacidade { readonly nome: string; podeGuardar(bytes: number): boolean; } export class Plano implements Capacidade { private readonly limiteBytes: number; readonly nome: string; constructor(nome: string, limiteBytes: number) { this.nome = nome; this.limiteBytes = limiteBytes; } podeGuardar(bytes: number): boolean { return Number.isFinite(bytes) && bytes >= 0 && bytes <= this.limiteBytes; } }"},{"path":"tsconfig.json","content":"{\"compilerOptions\":{\"target\":\"es2024\",\"module\":\"nodenext\",\"strict\":true,\"erasableSyntaxOnly\":true,\"verbatimModuleSyntax\":true,\"allowImportingTsExtensions\":true,\"noEmit\":true}}"},{"path":"package.json","content":"{\"type\":\"module\"}"}],"mutantDirs":[{"id":"accept-negative","files":[{"path":"main.ts","content":"export interface Capacidade { readonly nome: string; podeGuardar(bytes: number): boolean; } export class Plano implements Capacidade { private readonly limiteBytes: number; readonly nome: string; constructor(nome: string, limiteBytes: number) { this.nome = nome; this.limiteBytes = limiteBytes; } podeGuardar(bytes: number): boolean { return bytes <= this.limiteBytes; } }"}]}],"contractTypeFiles":[{"path":"contracts/17.11.types.ts","content":"import {Plano} from '../main.js';\nimport type {Capacidade} from '../main.js';\nconst plano = new Plano('Básico', 100);\nconst publico: Capacidade = plano;\nconst nome: string = publico.nome;\nconst aceito: boolean = publico.podeGuardar(100);\n// @ts-expect-error readonly name is not assignable\nplano.nome = 'Outro';\n// @ts-expect-error private quota cannot be read\nconst quota: number = plano.limiteBytes;\nvoid [nome, aceito, quota];"}],"typeContractMutants":[{"id":"name-not-readonly","files":[{"path":"main.ts","content":"export interface Capacidade { readonly nome: string; podeGuardar(bytes: number): boolean; } export class Plano implements Capacidade { private readonly limiteBytes: number; nome: string; constructor(nome: string, limiteBytes: number) { this.nome = nome; this.limiteBytes = limiteBytes; } podeGuardar(bytes: number): boolean { return Number.isFinite(bytes) && bytes >= 0 && bytes <= this.limiteBytes; } }"}]},{"id":"quota-not-private","files":[{"path":"main.ts","content":"export interface Capacidade { readonly nome: string; podeGuardar(bytes: number): boolean; } export class Plano implements Capacidade { public readonly limiteBytes: number; readonly nome: string; constructor(nome: string, limiteBytes: number) { this.nome = nome; this.limiteBytes = limiteBytes; } podeGuardar(bytes: number): boolean { return Number.isFinite(bytes) && bytes >= 0 && bytes <= this.limiteBytes; } }"}]}],"transfer":{"id":"17.11-transfer","files":[{"path":"transfer.md","content":"Modele outro limite com interface e propriedades explícitas. Mostre um consumidor que usa a interface, uma atribuição readonly inválida e uma chamada runtime na fronteira."}],"rubric":["O consumidor aceita a classe pela interface e rejeita em compilação a escrita readonly e o acesso ao campo privado.","A classe usa propriedades declaradas e atribuições explícitas no constructor sob erasableSyntaxOnly.","Os casos runtime aceitam valores finitos entre zero e o limite inclusive e rejeitam negativos e não finitos."]},"rubric":["A classe implementa Capacidade com membros compatíveis e mantém `private readonly limiteBytes` e `readonly nome`.","Os campos são declarados explicitamente e atribuídos no constructor; parameter properties não aparecem no código executável.","O método de runtime aceita apenas bytes finitos entre zero e o limite, inclusive."],"prompt":"Implemente Plano e demonstre o contrato de tipos e comportamento publicado.","sourceTestPath":"tests/17.11.test.js","tests":"import {Plano} from './main.ts';\n\ntest('Plano implementa a fronteira de capacidade', () => {\n  const plano = new Plano('Básico', 100);\n  expect(plano.podeGuardar(0)).toBe(true);\n  expect(plano.podeGuardar(100)).toBe(true);\n  expect(plano.podeGuardar(101)).toBe(false);\n  expect(plano.podeGuardar(-1)).toBe(false);\n  expect(plano.podeGuardar(Number.NaN)).toBe(false);\n  expect(plano.podeGuardar(Number.POSITIVE_INFINITY)).toBe(false);\n  expect(plano.nome).toBe('Básico');\n});\n"},"reference":[{"path":"main.ts","content":"export interface Capacidade {\n  readonly nome: string;\n  podeGuardar(bytes: number): boolean;\n}\n\nexport class Plano implements Capacidade {\n  private readonly limiteBytes: number;\n  readonly nome: string;\n\n  constructor(nome: string, limiteBytes: number) {\n    this.nome = nome;\n    this.limiteBytes = limiteBytes;\n  }\n\n  podeGuardar(bytes: number): boolean {\n    return Number.isFinite(bytes) && bytes >= 0 && bytes <= this.limiteBytes;\n  }\n}\n"},{"path":"package.json","content":"{\"type\":\"module\"}\n"},{"path":"tsconfig.json","content":"{\n  \"compilerOptions\": {\n    \"target\": \"es2024\",\n    \"module\": \"nodenext\",\n    \"strict\": true,\n    \"erasableSyntaxOnly\": true,\n    \"verbatimModuleSyntax\": true,\n    \"allowImportingTsExtensions\": true,\n    \"noEmit\": true\n  }\n}\n"}]},{"item":{"id":"22.11","title":"JSDoc e verificação de JavaScript","stage":"22","kind":"MAKE","contentVersion":1,"optional":false,"duration":"35 min","runtime":"TypeScript 7.0 strict · Node.js 24 LTS","compatibility":"`main.js` continua sendo JavaScript executável. `allowJs` inclui JS na análise, `checkJs` habilita a checagem do projeto e `@ts-check` habilita a checagem por arquivo. As verificações de tipos e os testes runtime são gates separados.","objective":"Leia os tipos JSDoc de partida e preveja por que Number.isFinite e o retorno conflitam com eles; indique também o caso runtime que deve lançar RangeError.","prompt":"Corrija as anotações JSDoc e complete `calcularFrete` em `main.js`, mantendo o arquivo JavaScript. Use `// @ts-check` e tipos corretos para `pesoKg: number`, `expressa?: boolean` e retorno `number`. Para este projeto, `checkJs: true` ativa a checagem dos arquivos JavaScript; o site verifica os tipos e executa os testes.","firstResponse":{"action":"Leia os tipos JSDoc de partida e preveja por que Number.isFinite e o retorno conflitam com eles; indique também o caso runtime que deve lançar RangeError.","timing":"2 min"},"explanation":{"mental_model":"JSDoc descreve assinaturas que o TypeScript pode conferir sem renomear `.js` para `.ts`. `// @ts-check` ativa a checagem naquele arquivo; `checkJs: true` aplica a checagem a todos os `.js` incluídos.","worked_example":"`/** @param {number} pesoKg @param {boolean} [expressa=false] @returns {number} */` documenta uma função JavaScript. O checker compara chamadas e corpo com essas anotações; a suíte executa o JavaScript real.","common_trap":"Um comentário sem tipos úteis deixa parâmetros ou retornos implícitos em `any`; ausência de diagnóstico não prova um contrato. Typechecks também não provam o valor retornado em runtime.","why_it_matters":"Checagem gradual permite explicitar tipos e encontrar erros em módulos JavaScript sem conversão imediata para TypeScript."},"interaction":"Corrija JSDoc e corpo, depois compare typecheck com a execução dos casos protegidos. Alternativa acessível: use Tab para percorrer os casos e ler as mensagens anunciadas.","resources":["TypeScript Handbook — JSDoc Supported Types: https://www.typescriptlang.org/docs/handbook/jsdoc-supported-types.html","TypeScript TSConfig — checkJs: https://www.typescriptlang.org/tsconfig/checkJs.html"],"starterFiles":[{"path":"main.js","content":"// @ts-check\n\n/**\n * Calcula o frete em unidades monetárias para um peso positivo em kg.\n * @param {string} pesoKg\n * @param {boolean} [expressa=false]\n * @returns {string}\n */\nexport function calcularFrete(pesoKg, expressa = false) {\n  if (!Number.isFinite(pesoKg) || pesoKg <= 0) {\n    throw new RangeError('O peso deve ser positivo e finito.');\n  }\n  // Implemente: frete comum custa 8 por kg; expresso custa 10 por kg.\n  return 0;\n}\n"},{"path":"tsconfig.json","content":"{\n  \"compilerOptions\": {\n    \"target\": \"es2024\",\n    \"module\": \"nodenext\",\n    \"strict\": true,\n    \"allowJs\": true,\n    \"checkJs\": true,\n    \"noEmit\": true\n  }\n}\n"}],"assets":[],"examples":[{"given":"calcularFrete(2)","expected":"16; a chamada correta compila e executa"}],"checks":[{"fixture":{"given":"calcularFrete(2)","expected":"16; a chamada correta compila e executa"},"scoring":"Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."}],"constraints":[],"rubric":["Aceite qualquer implementação que cumpra entrada, saída, erro e efeitos declarados."],"learningMetadata":{"requires":["15.01","14.04","22.01"]},"edgeCases":["peso inválido -> RangeError; strings e resultado string são rejeitados por contratos protegidos; parâmetro ou retorno any falha IsAny"],"primers":["JSDoc pode tipar uma função JavaScript sem converter o arquivo para `.ts`. `// @ts-check` ativa checagem naquele arquivo; neste exercício, `checkJs: true` no `tsconfig` oferece a mesma checagem em escopo de projeto."],"review":{"prompt":"O que ativa a checagem de tipos num arquivo JavaScript?","choices":["Apenas mudar a extensão para `.ts`","Adicionar `@returns` sem executar o TypeScript","`// @ts-check` no arquivo ou `checkJs: true` no projeto","Rodar JavaScript com Node.js"],"answer":2,"correctFeedback":"Correto: são dois controles de escopo diferentes para o checker TypeScript.","incorrectFeedback":"Extensão, JSDoc isolado ou execução Node não substituem a configuração da verificação."},"assessmentEnvironment":"typescript","autoTested":true,"preparation":{"guided":true,"stageTitle":"PACOTES, .D.TS E SCHEMAS","introduction":"Leia os tipos JSDoc de partida e preveja por que Number.isFinite e o retorno conflitam com eles; indique também o caso runtime que deve lançar RangeError.","explanation":"JSDoc descreve assinaturas que o TypeScript pode conferir sem renomear `.js` para `.ts`. `// @ts-check` ativa a checagem naquele arquivo; `checkJs: true` aplica a checagem a todos os `.js` incluídos.","conceptSteps":["JSDoc descreve assinaturas que o TypeScript pode conferir sem renomear `.js` para `.ts`.","`// @ts-check` ativa a checagem naquele arquivo; `checkJs: true` aplica a checagem a todos os `.js` incluídos.","Checagem gradual permite explicitar tipos e encontrar erros em módulos JavaScript sem conversão imediata para TypeScript."],"vocabulary":["`any` — Um comentário sem tipos úteis deixa parâmetros ou retornos implícitos em `any`; ausência de diagnóstico não prova um contrato."],"workedExample":{"steps":["`/** @param {number} pesoKg @param {boolean} [expressa=false] @returns {number} */` documenta uma função JavaScript.","O checker compara chamadas e corpo com essas anotações; a suíte executa o JavaScript real."]},"notes":["Um comentário sem tipos úteis deixa parâmetros ou retornos implícitos em `any`; ausência de diagnóstico não prova um contrato. Typechecks também não provam o valor retornado em runtime.","Checagem gradual permite explicitar tipos e encontrar erros em módulos JavaScript sem conversão imediata para TypeScript."],"docs":[{"title":"TypeScript Handbook — JSDoc Supported Types","url":"https://www.typescriptlang.org/docs/handbook/jsdoc-supported-types.html","section":"","question":""},{"title":"TypeScript TSConfig — checkJs","url":"https://www.typescriptlang.org/tsconfig/checkJs.html","section":"","question":""}],"materials":[],"predictionGuide":"Leia os tipos JSDoc de partida e preveja por que Number.isFinite e o retorno conflitam com eles; indique também o caso runtime que deve lançar RangeError. 2 min","practiceSteps":["Corrija as anotações JSDoc e complete `calcularFrete` em `main.js`, mantendo o arquivo JavaScript.","Use `// @ts-check` e tipos corretos para `pesoKg: number`, `expressa?: boolean` e retorno `number`.","Para este projeto, `checkJs: true` ativa a checagem dos arquivos JavaScript; o site verifica os tipos e executa os testes."],"hints":["Releia o enunciado e separe entrada, saída e restrições: Corrija as anotações JSDoc e complete `calcularFrete` em `main.js`, mantendo o arquivo JavaScript. Use `// @ts-check` e tipos corretos para `pesoKg: number`, `expressa?: boolean` e retorno `number`. Para este projeto, `checkJs: true` ativa ","Compare com o exemplo público — dado: calcularFrete(2). Esperado: 16; a chamada correta compila e executa.","Cuidado com a armadilha desta atividade: Um comentário sem tipos úteis deixa parâmetros ou retornos implícitos em `any`; ausência de diagnóstico não prova um contrato."],"reflectionPrompt":"Compare sua primeira resposta com o resultado da tentativa. Explique a regra que você praticou e um erro que ela ajuda a evitar."},"hints":["Releia o enunciado e separe entrada, saída e restrições: Corrija as anotações JSDoc e complete `calcularFrete` em `main.js`, mantendo o arquivo JavaScript. Use `// @ts-check` e tipos corretos para `pesoKg: number`, `expressa?: boolean` e retorno `number`. Para este projeto, `checkJs: true` ativa ","Compare com o exemplo público — dado: calcularFrete(2). Esperado: 16; a chamada correta compila e executa.","Cuidado com a armadilha desta atividade: Um comentário sem tipos úteis deixa parâmetros ou retornos implícitos em `any`; ausência de diagnóstico não prova um contrato."]},"assessment":{"environment":"typescript","version":1,"checks":["types","behavior","mutation"],"entryPath":"main.js","tsconfigPath":"tsconfig.json","testPath":"__devpath_tests__.js","behaviorTestPath":"__devpath_protected_behavior__.js","referenceDir":"solutions/22.11","correctFiles":[{"path":"main.js","content":"// @ts-check\n/** @param {number} pesoKg @param {boolean} [expressa=false] @returns {number} */ export function calcularFrete(pesoKg, expressa = false) { if (!Number.isFinite(pesoKg) || pesoKg <= 0) throw new RangeError('O peso deve ser positivo e finito.'); return pesoKg * (expressa ? 10 : 8); }"},{"path":"tsconfig.json","content":"{\"compilerOptions\":{\"target\":\"es2024\",\"module\":\"nodenext\",\"strict\":true,\"allowJs\":true,\"checkJs\":true,\"noEmit\":true}}"},{"path":"package.json","content":"{\"type\":\"module\"}"}],"mutantDirs":[{"id":"wrong-express-rate","files":[{"path":"main.js","content":"// @ts-check\n/** @param {number} pesoKg @param {boolean} [expressa=false] @returns {number} */ export function calcularFrete(pesoKg, expressa = false) { if (!Number.isFinite(pesoKg) || pesoKg <= 0) throw new RangeError('O peso deve ser positivo e finito.'); return pesoKg * (expressa ? 8 : 10); }"}]}],"contractTypeFiles":[{"path":"contracts/22.11.types.ts","content":"import {calcularFrete} from '../main.js';\ntype IsAny<T> = 0 extends (1 & T) ? true : false;\ntype NotAny<T extends false> = T;\ntype Weight = NotAny<IsAny<Parameters<typeof calcularFrete>[0]>>;\ntype Result = NotAny<IsAny<ReturnType<typeof calcularFrete>>>;\nconst comum: number = calcularFrete(2);\nconst expressa: number = calcularFrete(2, true);\n// @ts-expect-error weight must be numeric\ncalcularFrete('2');\n// @ts-expect-error expressa must be boolean\ncalcularFrete(2, 'sim');\nvoid [comum, expressa];"}],"typeContractMutants":[{"id":"parameter-is-any","files":[{"path":"main.js","content":"// @ts-check\n/** @param {*} pesoKg @param {boolean} [expressa=false] @returns {number} */ export function calcularFrete(pesoKg, expressa = false) { if (!Number.isFinite(pesoKg) || pesoKg <= 0) throw new RangeError('O peso deve ser positivo e finito.'); return pesoKg * (expressa ? 10 : 8); }"}]},{"id":"return-is-any","files":[{"path":"main.js","content":"// @ts-check\n/** @param {number} pesoKg @param {boolean} [expressa=false] @returns {*} */ export function calcularFrete(pesoKg, expressa = false) { if (!Number.isFinite(pesoKg) || pesoKg <= 0) throw new RangeError('O peso deve ser positivo e finito.'); return pesoKg * (expressa ? 10 : 8); }"}]},{"id":"missing-jsdoc","files":[{"path":"main.js","content":"// @ts-check\nexport function calcularFrete(pesoKg, expressa = false) { if (!Number.isFinite(pesoKg) || pesoKg <= 0) throw new RangeError('O peso deve ser positivo e finito.'); return pesoKg * (expressa ? 10 : 8); }"}]}],"transfer":{"id":"22.11-transfer","files":[{"path":"transfer.md","content":"Tipar por JSDoc uma função `.js` que recebe uma lista e devolve uma quantidade; acrescente contrato consumidor válido/inválido e um teste runtime."}],"rubric":["O arquivo continua `.js` e a função exportada tem JSDoc de parâmetros e retorno sem any.","O projeto ativa allowJs/checkJs para a verificação estática, sem substituir o teste runtime.","O contrato de consumidor aceita chamadas válidas e rejeita tipos errados; os testes comprovam resultado e RangeError."]},"rubric":["A implementação permanece em `main.js` com `@ts-check` e JSDoc explícito para parâmetros e retorno.","`allowJs`, `checkJs` e `strict` fazem parte da configuração real usada pelo checker do site.","Contratos protegidos rejeitam parâmetros/retornos any e remoção das anotações; a suíte separada executa casos válidos e inválidos."],"prompt":"Implemente `calcularFrete` em JavaScript com JSDoc e prove tipos e comportamento no site.","sourceTestPath":"tests/22.11.test.js","tests":"import {calcularFrete} from './main.js';\n\ntest('calcula frete comum e expresso', () => {\n  expect(calcularFrete(2)).toBe(16);\n  expect(calcularFrete(2, true)).toBe(20);\n});\n\ntest('rejeita peso inválido antes de calcular', () => {\n  expect(() => calcularFrete(0)).toThrow(RangeError);\n  expect(() => calcularFrete(Number.NaN)).toThrow(RangeError);\n  expect(() => calcularFrete(Number.POSITIVE_INFINITY)).toThrow(RangeError);\n});\n"},"reference":[{"path":"main.js","content":"// @ts-check\n\n/**\n * Calcula o frete em unidades monetárias para um peso positivo em kg.\n * @param {number} pesoKg\n * @param {boolean} [expressa=false]\n * @returns {number}\n */\nexport function calcularFrete(pesoKg, expressa = false) {\n  if (!Number.isFinite(pesoKg) || pesoKg <= 0) {\n    throw new RangeError('O peso deve ser positivo e finito.');\n  }\n  return pesoKg * (expressa ? 10 : 8);\n}\n"},{"path":"tsconfig.json","content":"{\n  \"compilerOptions\": {\n    \"target\": \"es2024\",\n    \"module\": \"nodenext\",\n    \"strict\": true,\n    \"allowJs\": true,\n    \"checkJs\": true,\n    \"noEmit\": true\n  }\n}\n"}]}];
  const results = [];
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  for (const row of payload) {
    const id = row.item.id;
    await page.goto('http://127.0.0.1:8765/devpath.html#/javascript/' + id);
    await page.getByRole('button', {name: 'Aprender este conceito', exact: true}).waitFor({state: 'visible'});
    await page.getByRole('button', {name: 'Aprender este conceito', exact: true}).click();
    const prediction = page.locator(`[data-first-response-input="${id}"]`);
    await prediction.waitFor({state: 'visible'});
    await prediction.fill('Vou conferir o contrato, os tipos de entrada e cada caso de borda antes de implementar.');
    await page.locator(`[data-course-first-response="${id}"]`).click();
    const editor = page.locator(`[data-course-editor="${id}"]`).first();
    await editor.waitFor({state: 'visible'});
    const outcomes = await page.evaluate(async ({item, assessment, reference}) => {
      const run = files => window.DevPathAssessment.run({item, assessment, files, fingerprint: 'browser-phase1-' + item.id});
      let starter = await run(item.starterFiles);
      if (starter.kind === 'timeout') starter = await run(item.starterFiles);
      let solution = await run(reference);
      if (solution.kind === 'timeout') solution = await run(reference);
      return {starter: {kind: starter.kind, tests: starter.tests, text: starter.text}, reference: {kind: solution.kind, tests: solution.tests, text: solution.text}};
    }, row);
    if (outcomes.reference.kind !== 'passed' || !['failed', 'type-error'].includes(outcomes.starter.kind)) throw new Error(id + ': ' + JSON.stringify(outcomes));
    for (const file of row.reference) {
      const field = page.locator(`[data-course-editor="${id}"][data-course-file="${file.path}"]`);
      if (await field.count()) await field.fill(file.content);
    }
    await page.locator(`[data-course-run="${id}"]`).click();
    await page.waitForFunction(id => {
      const text = document.querySelector(`[data-course-output="${id}"]`)?.textContent || '';
      return text && !text.includes('Preparando avaliação local') && !text.includes('A saída aparecerá');
    }, id, {timeout: 30000});
    const uiOutput = await page.locator(`[data-course-output="${id}"]`).textContent();
    if (uiOutput.includes('Corrija o trabalho')) throw new Error(id + ' UI reference failed: ' + uiOutput);
    await page.locator(`[data-course-reflection="${id}"]`).fill('Conferi cada caso de borda no código e os testes mostram os resultados previstos pelo contrato.');
    const criteria = page.locator(`[data-course-rubric="${id}"]`);
    for (let n = 0; n < await criteria.count(); n++) await criteria.nth(n).check();
    const complete = page.locator(`[data-course-complete="${id}"]`);
    if (await complete.isDisabled()) throw new Error(id + ': completion unavailable after passing');
    await complete.click();
    await page.waitForFunction(id => JSON.parse(localStorage.getItem('devpath-local-preview-v1') || '{}').answers?.[id] === true, id);
    const draft = await editor.inputValue();
    await page.waitForTimeout(700);
    await page.reload();
    await editor.waitFor({state: 'visible'});
    const restored = await editor.inputValue();
    if (draft !== restored) throw new Error(id + ': draft lost on reload');
    const record = await page.evaluate(id => {
      const progress = JSON.parse(localStorage.getItem('devpath-local-preview-v1') || '{}');
      return {completed: progress.answers?.[id], state: progress.exerciseLearning?.[id]?.state};
    }, id);
    if (!record.completed || record.state !== 'verified') throw new Error(id + ': persisted evidence invalid: ' + JSON.stringify(record));
    results.push({id, ...outcomes, uiPassed: true, draftRestored: true, ...record});
  }
  if (errors.length) throw new Error('Page errors: ' + errors.join('; '));
  await browserContext.close();
  return {results, pageErrors: errors};
})